"""Toolstation UK complete crawlable category inventory.

Captured 2026-10-15 from the authoritative first-party category sitemap
(``https://www.toolstation.com/sitemap/departments.xml``, advertised in
``robots.txt``). Every entry is a real Toolstation taxonomy listing URL of the
form ``/{department}/[.../]{leaf}/c<id>``; the spider sends the ``c<id>`` to the
Bloomreach CRS search API, so no HTML is involved.

The inventory is the grouped ``{department: {leaf: {name, department,
category_id, path, url[, products]}}}`` mapping required by
:class:`BaseListingSpider`. There are **1,015** leaves across **27** departments.
Leaf keys are the full path slug (``<department>-...-<leaf>-<id>``); the trailing
``-<c<id>>`` only appears on the four URLs that would otherwise collide
(``lighting/ceiling-lights/c951`` vs ``c954`` and ``lighting/wall-lights/c952``
vs ``c955``), so every key is globally unique and the Airflow task id and GCS
output path cannot clash.

``products`` is the sitemap-derived inventory count carried over from the review
sample where it was recorded.

``-a category=<department-slug>`` still expands to every leaf in that department
through the base-class parent selector.
"""

