# Reviewed top-20 coverage preserved from the original seed list. The DAG
# schedules at most MAX_TASK_SUBCATEGORIES (3) leaves per group, so the whole
# inventory stays available for `-a category=<leaf>` without exploding the DAG.
_TOOLSTATION_DAG_CATEGORY_IDS = {
    'c1468',
    'c1500',
    'c1478',
    'c1089',
    'c715',
    'c713',
    'c660',
    'c728',
    'c1562',
    'c207',
    'c794',
    'c769',
    'c1463',
    'c692',
    'c680',
    'c737',
    'c678',
    'c781',
    'c1090',
    'c968',
}

TOOLSTATION_DAG_CATEGORIES = {
    group: {
        leaf: entry
        for leaf, entry in leaves.items()
        if entry["category_id"] in _TOOLSTATION_DAG_CATEGORY_IDS
    }
    for group, leaves in TOOLSTATION_CATEGORIES.items()
    if any(
        entry["category_id"] in _TOOLSTATION_DAG_CATEGORY_IDS
        for entry in leaves.values()
    )
}
